import assert from 'node:assert/strict';
import vm from 'node:vm';
import path from 'node:path';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
const root = '<repository-root>';
const out = path.resolve(process.argv[2]); mkdirSync(out);
const sha = b => createHash('sha256').update(b).digest('hex');
const htmlPath = path.join(root, 'dist/index.html'), ioPath = path.join(root, 'scripts/check-report-recovery.mjs');
const originalPath = path.join(root, 'docs/qa/runs/npc-rest-work-v1-20261018/legacy/objects/ebd2c2a6f1ab12b0e62dc6ba235231b4a229916759cdf1662c2594ed9ac4c7e6.json');
const sourceBytes = readFileSync(htmlPath), ioBytes = readFileSync(ioPath), originalBytes = readFileSync(originalPath), methodBytes = readFileSync(fileURLToPath(import.meta.url));
const html = sourceBytes.toString('utf8'), io = ioBytes.toString('utf8');
const inline = [...html.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/g)].map(m => m[1]).filter(t => t.trim()); assert.equal(inline.length, 1);
const a = io.indexOf('function runtime(entries = []) {'), b = io.indexOf('\nfunction envelope(payload)', a); assert.ok(a >= 0 && b > a);
const fragment = io.slice(a, b), marker = 'registry: EVENT_DEFS, hash: checksum,'; assert.equal(fragment.split(marker).length, 2);
const saveKey = 'zombie-harvest-progress-v12';
const factory = vm.runInNewContext('(' + fragment.replace(marker, 'attack, ' + marker).trim() + ')', { inline, htmlPath, vm, assert, console, URLSearchParams, saveKey });
const hasher = factory(), original = JSON.parse(originalBytes), p = structuredClone(original.payload);
p.player.x = 1; p.player.y = 20; const z = p.worldZombies.find(e => e.id === 'wz-4'); z.x = 2; z.y = 20;
p.worldMeta.clock.paused = false; p.worldMeta.clock.rate = 0.25;
const raw = JSON.stringify({ version: p.version, payload: p, checksum: hasher.api.hash(p), savedAt: p.world.totalMinutes, reason: 'TEST-ONLY rate .25 and close geometry' });
const r = factory([[saveKey, raw]]), beforeValidation = r.api.validate({ raw, sourceCategory: 'primary' });
assert.equal(beforeValidation.ok, true, JSON.stringify(beforeValidation));
const started = r.api.start(); assert.equal(started.ok, true); r.tasks.clear();
const before = JSON.parse(JSON.stringify({ minute: r.api.state.world.totalMinutes, energy: r.api.state.energy, target: r.api.state.worldZombies.find(e => e.id === 'wz-4'), roster: r.api.state.npcs.map(n => n.id), enemyIds: r.api.state.worldZombies.map(e => e.id) }));
const attack = r.api.attack({ targetId: 'wz-4', commandId: 'quarter-rate-actual-attack' });
const afterAction = JSON.parse(JSON.stringify({ minute: r.api.state.world.totalMinutes, energy: r.api.state.energy, target: r.api.state.worldZombies.find(e => e.id === 'wz-4') }));
const writerReturn = r.api.save(), stored = r.storage.get(saveKey), storedObject = JSON.parse(stored);
const storedValidation = r.api.validate({ raw: stored, sourceCategory: 'primary' }), payloadValidation = r.api.validatePayload(storedObject.payload || storedObject);
const inputs = [['source.html', sourceBytes], ['io-executed.mjs', ioBytes], ['original-writer.json', originalBytes], ['method-executed.mjs', methodBytes], ['derived-input.json', raw], ['actual-writer-output.json', stored]];
const artifacts = inputs.map(([name, data]) => { writeFileSync(path.join(out, name), data); return { path: name, bytes: Buffer.byteLength(data), sha256: sha(data) }; });
const report = { schema: 'PlayerDayAttackQuarterRateDiagnosticV1', sourceHtmlSha256: sha(sourceBytes), ioSha256: sha(ioBytes), runtimeFactorySha256: sha(fragment), methodSha256: sha(methodBytes), originalWriterSha256: sha(originalBytes), derivedInputSha256: sha(raw), beforeValidation, started, before, attack, afterAction, writerReturn, storedValidation, payloadValidation, artifacts, testOnly: true, naturalGameplay: false, scope: 'Single actual source attack/normal writer/validator diagnostic, actual damage and advance unchanged; only preboot geometry and rate differ from original full writer.' };
writeFileSync(path.join(out, 'report.json'), JSON.stringify(report, null, 2) + '\n');
for (const [file, bytes] of [[htmlPath, sourceBytes], [ioPath, ioBytes], [originalPath, originalBytes]]) assert.equal(sha(readFileSync(file)), sha(bytes), 'actual input remained immutable');
console.log(JSON.stringify({ sourceHtmlSha256: report.sourceHtmlSha256, started, attackOk: attack.ok, actualMinute: afterAction.minute, writerReturn, storedValidation, payloadValidation, reportSha256: sha(readFileSync(path.join(out, 'report.json'))) }));
